// Vercel serverless function — returns the committed fleet RAG snapshot.
// The snapshot is regenerated by `.github/workflows/refresh-rag-snapshot.yml` (or
// manually via `scripts/build-rag-snapshot.mjs`); the browser never reaches the
// recall corpus directly because the Cloudflare Access gate on agents.jays.services
// requires a service token we don't ship to Vercel.

// A static import makes the snapshot an explicit function dependency.  It is not
// placed in public/ and cannot be downloaded as a static repository file.
const snapshot = require("../site-snapshot.json");

module.exports = async function (req, res) {
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  // This is private operator data; avoid persistence in shared or browser caches.
  res.setHeader("Cache-Control", "private, no-store");
  res.setHeader("Access-Control-Allow-Origin", "https://home.jays.services");
  res.status(200).json(snapshot);
};
